const savedLanguage=localStorage.getItem('webapp_lang');
const visitorId=localStorage.getItem('webapp_visitor_id')||crypto.randomUUID();localStorage.setItem('webapp_visitor_id',visitorId);
const state={lang:I18N[savedLanguage]?savedLanguage:'uz',view:'permit',countrySource:[],countries:[],pickers:{},direction:'entry',posts:[],map:null,mapResizeStop:null,markers:new Map(),borderLayer:null,borderPromise:null,lastResult:null,oversize:{map:null,resizeStop:null,start:null,finish:null,markers:[],routeLayers:[],routes:[],routeId:'',carrier:'local',borderLayer:null}};
let yandexMapsPromise=null;
const $=id=>document.getElementById(id),tr=key=>I18N[state.lang][key]||key;
function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function icon(name){return `<svg class="icon" aria-hidden="true"><use href="#icon-${name}"></use></svg>`}
function flagMarkup(iso,name=''){const code=String(iso||'').toLowerCase();if(!/^[a-z]{2}$/.test(code))return icon('globe');const fallback=icon('globe').replace('<svg','<svg hidden');return `<img class="country-flag" src="/static/webapp/flags/${code}.svg" alt="${escapeHTML(name)}" loading="lazy" decoding="async" onerror="this.hidden=true;this.nextElementSibling.hidden=false">${fallback}`}
function setPickerFlag(element,country){element.innerHTML=country?flagMarkup(country.iso,country.name):icon('globe')}
function normalize(value){return String(value||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f'’‘ʻʼ`]/g,'').replace(/[^a-zа-я0-9]/g,'')}
function editDistance(a,b){const previous=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let diagonal=previous[0];previous[0]=i;for(let j=1;j<=b.length;j++){const saved=previous[j];previous[j]=Math.min(previous[j]+1,previous[j-1]+1,diagonal+(a[i-1]===b[j-1]?0:1));diagonal=saved}}return previous[b.length]}
function countryScore(country,query){if(!query)return 1;if(country.code.includes(query))return 100;const name=normalize(country.name);if(name===query)return 120;if(name.startsWith(query))return 110;if(name.includes(query))return 100;const distance=editDistance(name,query),similarity=1-distance/Math.max(name.length,query.length,1);return similarity>=.6?similarity*90:0}
function formatSom(value){return new Intl.NumberFormat(state.lang==='ru'?'ru-RU':state.lang==='en'?'en-US':'uz-UZ').format(value)+' UZS'}
function formatUsd(value){return new Intl.NumberFormat(state.lang==='ru'?'ru-RU':state.lang==='en'?'en-US':'uz-UZ',{maximumFractionDigits:2}).format(value)+' USD'}
function setBusy(form,busy){const button=form.querySelector('.primary-action');button.disabled=busy;button.classList.toggle('loading',busy)}
function showError(id,message){const el=$(id);el.textContent=message;el.hidden=!message}
function toast(message){const el=$('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,2400)}
async function api(path,body){const payload=body?{...body,visitor_id:visitorId}:undefined;const response=await fetch(path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined});if(!response.ok)throw new Error((await response.text())||tr('serverError'));return response.json()}
function applyLanguage(){document.documentElement.lang=state.lang;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=tr(el.dataset.t));document.querySelectorAll('[data-t-placeholder]').forEach(el=>el.placeholder=tr(el.dataset.tPlaceholder));document.querySelectorAll('[data-lang]').forEach(el=>el.classList.toggle('active',el.dataset.lang===state.lang));localStorage.setItem('webapp_lang',state.lang);loadCountries();if(state.posts.length)loadPosts();if($('oversize-axles'))renderAxles();if(!document.querySelector('.result:not([hidden])'))return;document.querySelectorAll('.result').forEach(el=>el.hidden=true)}
function localizedCountryName(country){if(country?.labels?.[state.lang])return country.labels[state.lang];if(!country?.iso)return country?.name||'';try{return new Intl.DisplayNames([state.lang],{type:'region'}).of(country.iso)||country.name}catch{return country.name}}
function mapCountries(){state.countries=state.countrySource.map(country=>({...country,name:localizedCountryName(country)})).sort((a,b)=>a.code==='000'?-1:b.code==='000'?1:a.name.localeCompare(b.name,state.lang));Object.values(state.pickers).forEach(p=>{if(p.value){const country=state.countries.find(c=>c.code===p.value);if(country){p.input.value=country.name;setPickerFlag(p.flag,country)}}});updateConditionalFields()}
async function loadCountries(){if(state.countrySource.length){mapCountries();return}try{const data=await api('/api/webapp/countries?lang=uz');state.countrySource=data.countries;mapCountries()}catch(error){console.error('Country list could not be loaded',error);showError('permit-error',error.message||tr('serverError'));toast(error.message||tr('serverError'))}}
function initPicker(root){const name=root.dataset.name,input=root.querySelector('input'),list=root.querySelector('.picker-list'),flagEl=root.querySelector('.picker-flag');const picker={root,input,list,flag:flagEl,value:''};state.pickers[name]=picker;
 function render(){const query=normalize(input.value);const rows=state.countries.map(country=>({country,score:countryScore(country,query)})).filter(row=>row.score>0).sort((a,b)=>b.score-a.score||a.country.name.localeCompare(b.country.name,state.lang)).slice(0,25).map(row=>row.country);list.innerHTML=rows.length?rows.map(c=>`<button type="button" class="picker-option" data-code="${c.code}"><span class="option-flag">${flagMarkup(c.iso,c.name)}</span><b>${escapeHTML(c.name)}</b><small>${c.code}</small></button>`).join(''):`<div class="picker-option">${escapeHTML(tr('noCountry'))}</div>`;list.hidden=false}
 input.addEventListener('focus',render);input.addEventListener('input',()=>{picker.value='';setPickerFlag(flagEl,null);afterPickerChange(name);render()});list.addEventListener('mousedown',e=>e.preventDefault());list.addEventListener('click',e=>{const option=e.target.closest('[data-code]');if(!option)return;const country=state.countries.find(c=>c.code===option.dataset.code);picker.value=country.code;input.value=country.name;setPickerFlag(flagEl,country);list.hidden=true;afterPickerChange(name)});root.querySelector('.clear').addEventListener('click',()=>{picker.value='';input.value='';setPickerFlag(flagEl,null);afterPickerChange(name);input.focus()});root.addEventListener('focusout',()=>setTimeout(()=>{if(!root.contains(document.activeElement))list.hidden=true},0));}
document.querySelectorAll('.country-picker').forEach(initPicker);
function pickerValue(name){const picker=state.pickers[name];if(!picker)return'';if(picker.value)return picker.value;const query=normalize(picker.input.value);const exact=state.countries.find(country=>normalize(country.name)===query||country.code===query);if(exact){picker.value=exact.code;picker.input.value=exact.name;setPickerFlag(picker.flag,exact);return exact.code}return''}
function selectedCountry(name){return state.countries.find(country=>country.code===state.pickers[name]?.value)}
function updateConditionalFields(){const permit=selectedCountry('permit-vehicle'),fee=selectedCountry('fee-vehicle');$('permit-weight-field').hidden=!permit?.uses_weight;$('permit-days-field').hidden=!permit?.uses_stay_days;$('fee-weight-field').hidden=!fee?.uses_weight;$('fee-days-field').hidden=!fee?.uses_stay_days;$('fee-special-fields').hidden=!(fee?.uses_weight||fee?.uses_stay_days)}
function afterPickerChange(name){if(name==='permit-vehicle'||name==='fee-vehicle')updateConditionalFields()}
function setMapActivity(map,active){if(!map)return;try{const names=['drag','scrollZoom','multiTouch'];if(active)map.behaviors.enable(names);else map.behaviors.disable(names)}catch(_){}if(active)setTimeout(()=>{try{map.container.fitToViewport()}catch(_){}},80)}
function switchView(view){state.view=view;document.body.classList.toggle('map-mode',view==='posts');document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===view+'-view'));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));setMapActivity(state.map,view==='posts');setMapActivity(state.oversize.map,view==='oversize');if(view==='posts'){window.scrollTo({top:0});loadPosts()}else if(view==='oversize'){window.scrollTo({top:0,behavior:'smooth'});ensureOversizeMap()}else window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>switchView(el.dataset.view)));
document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>{state.lang=el.dataset.lang;applyLanguage()}));
$('permit-swap').addEventListener('click',()=>{const a=state.pickers['permit-origin'],b=state.pickers['permit-destination'];[a.value,b.value]=[b.value,a.value];const ca=state.countries.find(c=>c.code===a.value),cb=state.countries.find(c=>c.code===b.value);a.input.value=ca?.name||'';setPickerFlag(a.flag,ca);b.input.value=cb?.name||'';setPickerFlag(b.flag,cb)});
$('direction-tabs').addEventListener('click',e=>{const button=e.target.closest('[data-value]');if(!button)return;state.direction=button.dataset.value;$('direction-tabs').querySelectorAll('button').forEach(el=>el.classList.toggle('active',el===button))});
$('vehicle-type').addEventListener('change',()=>{const cargo=['truck','truck_trailer'].includes($('vehicle-type').value);document.querySelectorAll('.cargo-only').forEach(el=>el.hidden=!cargo);$('fee-route').hidden=!cargo});
$('fee-declared').addEventListener('change',()=>{$('customs-value-field').hidden=!$('fee-declared').checked});
function warningHTML(keys){if(!keys?.length)return'';return`<div class="notice"><b>${escapeHTML(tr('warnings'))}</b><ol>${keys.map(key=>`<li>${escapeHTML(tr('warn')[key]||key)}</li>`).join('')}</ol></div>`}
function additionalConditionsHTML(items){if(!items?.length)return'';const title={uz:"Qo'shimcha shartlar",ru:"Дополнительные условия",en:"Additional conditions"}[state.lang];return`<div class="rule-conditions"><div class="rule-conditions-title">${icon('info')}<b>${escapeHTML(title)}</b></div><ol>${items.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ol></div>`}
function resultHeader(canSave=state.lastResult?.kind==='permit'&&Boolean(window.Telegram?.WebApp?.initData)){return`<div class="result-head"><h2>${icon('file-check')} ${escapeHTML(tr('result'))}</h2><div class="result-actions">${canSave?`<button type="button" class="save-route" onclick="saveCurrentRoute()">${icon('bookmark')}<span>${escapeHTML(tr('saveRoute'))}</span></button>`:''}<button type="button" class="report-error" onclick="openFeedback()">${icon('alert')}<span>${escapeHTML(tr('reportError'))}</span></button><button type="button" onclick="copyResult(this)">${icon('copy')}<span>${escapeHTML(tr('copy'))}</span></button><button type="button" onclick="window.print()">${icon('printer')}<span>${escapeHTML(tr('print'))}</span></button></div></div>`}
window.copyResult=async button=>{const text=button.closest('.result-card').innerText;try{await navigator.clipboard.writeText(text);toast(tr('copied'))}catch{toast(tr('serverError'))}};
function permissionStatus(code){if(code==='1')return[tr('required'),'warn'];if(code==='2')return[tr('notRequired'),'good'];if(code==='3')return[tr('prohibited'),'bad'];return[tr('unknown'),'warn']}
function ruleFeeStatus(fee){if(fee.dues_code==='1')return[`${tr('charged')} · ${formatUsd(fee.total_usd||0)}`,'warn'];if(fee.dues_code==='2')return[tr('notCharged'),'good'];if(fee.dues_code==='3')return[tr('unknown'),'warn'];return[tr('notApplicable'),'muted']}
function exemptGoodsStatus(rule){const info=rule.permit_exempt_goods||{},count=Number(info.count||rule.exceptions?.length||0);if(count)return[`${tr('agreementExceptions')} · ${count}`,'good'];if(info.code==='2')return[tr('agreementExceptions'),'good'];if(info.code==='1')return[tr('notProvided'),'muted'];return[tr('notApplicable'),'muted']}
function ruleCard(rule){const [permitText,permitClass]=permissionStatus(rule.permission.code),[feeText,feeClass]=ruleFeeStatus(rule.fee),[goodsText,goodsClass]=exemptGoodsStatus(rule),conditions=additionalConditionsHTML(rule.additional_conditions),exceptions=rule.exceptions.length?`<details class="exceptions"><summary>${escapeHTML(tr('showExceptions'))} (${rule.exceptions.length})</summary><ol>${rule.exceptions.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol></details>`:'';return`<article class="rule-card ${permitClass}${rule.selected?' selected':''}"><div class="rule-card-head"><span class="rule-code">${escapeHTML(rule.transport_type.base_code)}</span><div><small>${escapeHTML(rule.selected?tr('selectedBadge'):tr('referenceBadge'))}</small><h3>${escapeHTML(rule.transport_type.name)}</h3></div>${rule.selected?`<span class="selected-pill">${escapeHTML(tr('selectedBadge'))}</span>`:''}</div><div class="rule-detail-grid"><div class="${permitClass}"><small>${escapeHTML(tr('permit'))}</small><b>${escapeHTML(permitText)}</b></div><div class="${goodsClass}"><small>${escapeHTML(tr('permitExemptGoods'))}</small><b>${escapeHTML(goodsText)}</b></div><div class="${feeClass}"><small>${escapeHTML(tr('fee'))}</small><b>${escapeHTML(feeText)}</b></div></div>${conditions}${exceptions}</article>`}
function renderPermit(data){const [status,cls]=permissionStatus(data.permission.code),fee=data.fee;const rows=[],baseDisplay=fee.base_before_discount_usd||fee.base_usd;rows.push(`<tr><td>${escapeHTML(tr('fee'))}</td><td>${fee.known?(baseDisplay?formatUsd(baseDisplay):tr('notCharged')):tr('unknown')}</td></tr>`);if(fee.base_before_discount_usd>fee.base_usd)rows.push(`<tr><td>${escapeHTML(tr('humanitarian'))} · 0.5</td><td>−${formatUsd(fee.base_before_discount_usd-fee.base_usd)}</td></tr>`);if(fee.extra_usd)rows.push(`<tr><td>Turkmenistan · qo'shimcha</td><td>${formatUsd(fee.extra_usd)}</td></tr>`);if(fee.permit_purchase_usd)rows.push(`<tr><td>${escapeHTML(tr('permitPurchase'))}</td><td>${formatUsd(fee.permit_purchase_usd)}</td></tr>`);const exceptions=data.exceptions.length?`<details class="exceptions"><summary>${escapeHTML(tr('exceptions'))} (${data.exceptions.length})</summary><p class="notice info">${escapeHTML(tr('exceptionNote'))}</p><ol>${data.exceptions.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol></details>`:'';
 const related=data.related_rules||[],orderedRules=related.slice().sort((a,b)=>Number(a.transport_type.base_code)-Number(b.transport_type.base_code)),rules=orderedRules.length?`<section class="rule-overview"><div class="rules-heading"><h2>${icon('file-check')} ${escapeHTML(tr('allRules'))}</h2><p>${escapeHTML(tr('rulesIntro'))}</p></div><div class="rule-grid">${orderedRules.map(ruleCard).join('')}</div></section>`:'';$('permit-result').innerHTML=`<div class="glass result-card">${resultHeader()}<div class="status-grid"><div class="status ${cls}"><small>${escapeHTML(tr('permit'))}</small><b>${escapeHTML(status)}</b></div><div class="status"><small>${escapeHTML(tr('transportType'))}</small><b>${escapeHTML(data.transport_type.name)}</b></div></div><table class="fee-table"><thead><tr><th>${escapeHTML(tr('payments'))}</th><th>${escapeHTML(tr('amount'))}</th></tr></thead><tbody>${rows.join('')}</tbody></table><div class="total-box"><span>${escapeHTML(tr('total'))}</span><b>${formatUsd(fee.total_usd)}</b></div>${rules}${additionalConditionsHTML(data.additional_conditions)}${warningHTML(data.warnings)}${data.notes[state.lang]?`<div class="notice info">${escapeHTML(data.notes[state.lang])}</div>`:''}${exceptions}</div>`;$('permit-result').hidden=false;$('permit-result').scrollIntoView({behavior:'smooth',block:'start'})}
$('permit-form').addEventListener('submit',async e=>{e.preventDefault();showError('permit-error','');const form=e.currentTarget,codes=['permit-origin','permit-destination','permit-vehicle'].map(pickerValue);if(codes.some(x=>!x)){showError('permit-error',tr('selectCountry'));return}setBusy(form,true);try{const data=await api('/api/webapp/permit',{lang:state.lang,origin:codes[0],destination:codes[1],vehicle:codes[2],weight:$('permit-weight').value,stay_days:$('permit-days').value,humanitarian:$('permit-humanitarian').checked,heavy:$('permit-heavy').checked,permit_purchase:$('permit-purchase').checked});setBusy(form,false);renderPermit(data)}catch(error){showError('permit-error',error.message||tr('serverError'))}finally{setBusy(form,false)}});
