async function addUzbekistanBorder(map,fit=true){
 const data=await api('/api/webapp/uzbekistan-border'),layer=new ymaps.GeoObjectCollection(),points=[];
 const addGeometry=geometry=>{if(!geometry)return;const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];polygons.forEach(polygon=>{const rings=polygon.map(ring=>ring.filter(point=>Array.isArray(point)&&Number.isFinite(Number(point[0]))&&Number.isFinite(Number(point[1]))).map(point=>[Number(point[1]),Number(point[0])])).filter(ring=>ring.length>=4);if(!rings.length)return;rings[0].forEach(point=>points.push(point));layer.add(new ymaps.Polygon(rings,{}, {fillColor:'#07997920',strokeColor:'#087f84',strokeWidth:3,strokeOpacity:.98,interactivityModel:'default#transparent'}));layer.add(new ymaps.Polyline(rings[0],{}, {strokeColor:'#ffffff',strokeWidth:6,strokeOpacity:.64,interactivityModel:'default#transparent',zIndex:149}));layer.add(new ymaps.Polyline(rings[0],{}, {strokeColor:'#087f84',strokeWidth:2.5,strokeOpacity:1,interactivityModel:'default#transparent',zIndex:150}))})};
 if(data?.type==='FeatureCollection')data.features.forEach(feature=>addGeometry(feature.geometry));else if(data?.type==='Feature')addGeometry(data.geometry);else addGeometry(data);
 map.geoObjects.add(layer);if(fit&&points.length){const lat=points.map(point=>point[0]),lon=points.map(point=>point[1]);map.setBounds([[Math.min(...lat),Math.min(...lon)],[Math.max(...lat),Math.max(...lon)]],{checkZoomRange:true,zoomMargin:28,duration:500})}
 return layer;
}
